67	function Framing({ bounds, resetToken }: { bounds: Sphere; resetToken: number }) {
68	  const { camera, controls, size } = useThree();
69	  useEffect(() => {
70	    const orbit = controls as unknown as OrbitLike | null;
71	    const perspective = camera as typeof camera & { fov?: number; aspect?: number };
72	    const vertical = MathUtils.degToRad(perspective.fov ?? 55);
73	    const horizontal = 2 * Math.atan(Math.tan(vertical / 2) * (size.width / Math.max(size.height, 1)));
74	    const radius = Math.max(bounds.radius, 0.001);
75	    const distance = radius / Math.sin(Math.min(vertical, horizontal) / 2) * 1.1;
76	    // A dollhouse view: about 50° down from the entrance side (+Z), so corridors read from above.
77	    camera.position.copy(bounds.center).add(new Vector3(0, distance * 0.77, distance * 0.64));
78	    camera.near = Math.max(radius / 1000, 0.00001);
79	    camera.far = Math.max(radius * 100, distance * 4);
80	    camera.updateProjectionMatrix();
81	    if (orbit) {
82	      orbit.target.copy(bounds.center);
83	      orbit.minDistance = radius * 0.005;
84	      orbit.maxDistance = Math.max(radius * 10, distance * 2);
85	      orbit.update();
86	    } else camera.lookAt(bounds.center);
87	  }, [bounds, camera, controls, resetToken, size.width, size.height]);
88	  return null;
89	}
