async function canvasShot(page: Page) { return page.locator("canvas").screenshot(); }
function screenPoint(box: { x: number; y: number; width: number; height: number }, bounds: Sphere, p: { x: number; y: number; z: number }) {
  // Same overview camera as Framing and pick() above.
  const camera = new PerspectiveCamera(55, box.width / box.height);
  const vertical = MathUtils.degToRad(55), horizontal = 2 * Math.atan(Math.tan(vertical / 2) * box.width / box.height);
  const distance = bounds.radius / Math.sin(Math.min(vertical, horizontal) / 2) * 1.1;
  camera.position.copy(bounds.center).add(new Vector3(0, distance * 0.77, distance * 0.64));
  camera.lookAt(bounds.center); camera.updateMatrixWorld();
  const screen = new Vector3(p.x, p.y, p.z).project(camera);
  return { x: box.x + (screen.x + 1) * box.width / 2, y: box.y + (1 - screen.y) * box.height / 2 };
}

